import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_counts_none_in_denominator():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_dedupe_keeps_last_record_then_sorts_by_day_and_id():
    old = {"id": "b", "day": 5, "converted": True}
    replacement = {"id": "b", "day": 2, "converted": False}
    a = {"id": "a", "day": 2, "converted": True}
    z = {"id": "z", "day": 1, "converted": False}
    assert dedupe_sessions([old, replacement, a, z]) == [z, a, replacement]


def test_parse_skips_comments_and_blank_lines_and_strips_fields():
    lines = ["", "   ", "  # comment", " a , 2 , 1 ", "b,1, 0", "c,3, "]
    assert parse_session_log(lines) == [
        {"id": "a", "day": 2, "converted": True},
        {"id": "b", "day": 1, "converted": False},
        {"id": "c", "day": 3, "converted": None},
    ]


@pytest.mark.parametrize('bad_line', ['a,1', 'a,1,0,extra', 'a,no,1'])
def test_parse_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r'line 4\b'):
        parse_session_log(['a,1,1', '', ' # skip', bad_line])


def test_daily_counts_fill_gaps_and_ignore_outside_days():
    events = parse_session_log(['a,1,1', 'b,2,1', 'c,2,1', 'd,4,0', 'e,6,1'])
    assert daily_conversion_counts(events, 2, 5) == [2, 0, 0, 0]
    assert daily_conversion_counts(events, 4, 2) == []


def test_trailing_window():
    assert conversions_in_window([1, 2, 3], 2) == 5
    assert conversions_in_window([1, 2, 3], 0) == 0
    assert conversions_in_window([1, 2, 3], 4) == 6


def test_summary_weights_sessions_and_uses_calendar_days():
    groups = {'a': parse_session_log(['a,1,1']), 'empty': [],
              'b': parse_session_log(['b,2,0', 'c,5,0'])}
    assert campaign_summary(groups, 4) == {'rate': 0.333, 'recent': 0, 'groups': 2}
    assert campaign_summary({'empty': []}, 7) == {'rate': 0.0, 'recent': 0, 'groups': 0}
    assert pooled_conversion_rate({}) == 0.0


def test_group_metrics_order_ties_and_empty_groups():
    hit, miss = {"converted": True}, {"converted": False}
    groups = {'z': [hit], 'empty': [], 'a': [hit], 'b': [miss]}
    assert top_converting_groups(groups, 2) == ['a', 'z']
    assert top_converting_groups(groups, 5) == ['a', 'z', 'b']
    assert list(conversion_rate_by_group(groups).items()) == [
        ('a', 1.0), ('b', 0.0), ('empty', None), ('z', 1.0),
    ]


def test_streak_resets_on_nonpositive_count():
    assert longest_conversion_streak([1, -1, 1, 2, 0, 1]) == 2
    assert longest_conversion_streak([]) == 0

